import{_ as e,o as l,c as a,a0 as o}from"./chunks/framework.DqMqoJl9.js";const i="/assets/4-network_20210628230126.C_3YwI_q.png",r="/assets/4-network_20210629192513.8yW98b9r.png",b=JSON.parse('{"title":"计算机网络","description":"","frontmatter":{},"headers":[],"relativePath":"interview/4-network.md","filePath":"interview/4-network.md","lastUpdated":1791426062000}'),h={name:"interview/4-network.md"};function n(s,t,d,c,p,u){return l(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="计算机网络" tabindex="-1">计算机网络 <a class="header-anchor" href="#计算机网络" aria-label="Permalink to &quot;计算机网络&quot;">​</a></h1><h2 id="_1-七层网络模型" tabindex="-1">1 七层网络模型 <a class="header-anchor" href="#_1-七层网络模型" aria-label="Permalink to &quot;1 七层网络模型&quot;">​</a></h2><h3 id="_1-1-知识点" tabindex="-1">1.1 知识点 <a class="header-anchor" href="#_1-1-知识点" aria-label="Permalink to &quot;1.1 知识点&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">OSI 7 层模型</th><th style="text-align:left;">TCP/IP 4 层模型</th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;">应用层<br>表示层<br>会话层</td><td style="text-align:left;">应用层</td><td style="text-align:left;">HTTP、FTP、DNS</td></tr><tr><td style="text-align:left;">传输层</td><td style="text-align:left;">传输层</td><td style="text-align:left;">TCP、UDP</td></tr><tr><td style="text-align:left;">网络层</td><td style="text-align:left;">网际互联层</td><td style="text-align:left;">IP</td></tr><tr><td style="text-align:left;">数据链路层</td><td style="text-align:left;">网络接口层</td><td style="text-align:left;">Ethernet 802.3</td></tr><tr><td style="text-align:left;">物理层</td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr></tbody></table><h2 id="_2-http" tabindex="-1">2 http <a class="header-anchor" href="#_2-http" aria-label="Permalink to &quot;2 http&quot;">​</a></h2><p><strong>HTTP 是什么：</strong></p><ol><li>HTTP 是一个两点之间传输文字、图片、音频、视频等超文本数据的约定和规范</li><li>浏览器里面请求资源就是使用 HTTP 协议</li></ol><p><strong>HTTP 请求方法：</strong></p><ol><li>GET：获取资源，可以理解为读取或者下载数据；</li><li>HEAD：获取资源的元信息；</li><li>POST：向资源提交数据，相当于写入或上传数据；</li><li>PUT：类似 POST；</li><li>DELETE：删除资源；</li><li>CONNECT：建立特殊的连接隧道；</li><li>OPTIONS：列出可对资源实行的方法；</li><li>TRACE：追踪请求 - 响应的传输路径</li></ol><p><strong>Restful 接口：</strong></p><ol><li>GET：查找</li><li>POST：新增</li><li>PUT：修改</li><li>DELETE：删除</li></ol><p><strong>GET/POST 的区别：</strong></p><ol><li>GET 请求的参数放在 URL 上面，POST 请求通过 request body 传递参数</li><li>Get 请求传输数据量小，Post 请求传输数据量大</li><li>POST 的安全性比 GET 的高</li></ol><h2 id="_3-https" tabindex="-1">3 https <a class="header-anchor" href="#_3-https" aria-label="Permalink to &quot;3 https&quot;">​</a></h2><h3 id="_3-1-https-的作用" tabindex="-1">3.1 https 的作用 <a class="header-anchor" href="#_3-1-https-的作用" aria-label="Permalink to &quot;3.1 https 的作用&quot;">​</a></h3><p>http 是明文的，数据会被篡改或伪造</p><p>https 全称是“HTTP over SSL/TLS”，也就是运行在 <code>SSL/TLS</code> 协议上的 <code>HTTP</code></p><blockquote><p>Https = Http + 加密 + 认证 + 完整性验证</p></blockquote><p><strong>https 的作用：</strong></p><ul><li><strong>数据加密</strong> 传输内容进行混淆</li><li><strong>身份验证</strong> 通信双方验证对方的身份真实性</li><li><strong>数据完整性保护</strong> 检测传输的内容是否被篡改或伪造</li></ul><h3 id="_3-2-tls-ssl-协议的握手过程" tabindex="-1">3.2 TLS/SSL 协议的握手过程 <a class="header-anchor" href="#_3-2-tls-ssl-协议的握手过程" aria-label="Permalink to &quot;3.2 TLS/SSL 协议的握手过程&quot;">​</a></h3><blockquote><p>SSL 工作在 OSI 七层模型中的表示层，TCP/IP 四层模型的应用层</p></blockquote><p>TLS 协议的握手过程:</p><ol><li>客户端先给服务端发送一个消息，消息内容包括：客户端支持的加密方式，支持的压缩方法，SSL 的版本号，客户端生成的随机数，文本内容“Hello”等</li><li>服务端接收到消息后，也回发一个 Hello，并携带从客户端支持的加密方式中选择的加密方式，服务端生成的随机数，服务端的 SSL 版本号等信息</li><li>随后服务器给客户端发送一个 Certificate 报文，报文中包含服务端的公钥证书</li><li>紧接着服务器给客户端发送 Server Hello Done, 表示最初的协商握手过程结束</li><li>客户端接收到服务端发送的握手结束的消息后，以 Client Key Exchange 作为回应，此报文中包含通信加密过程中使用的一种被称为 Pre-master secret 的随机密码串，并使用第三步接收到的公钥证书进行了加密</li><li>接着客户端发送 Change Cipher Spec 报文，该报文告知服务端，此步骤之后的所有数据将使用第五步中生成的 master secret 进行加密</li><li>随后客户端发送 Finish 报文，此报文中包含连接至今所有报文的整体校验值，用于完整性验证</li><li>服务端接收到客户端发送的 Change Cliper Spec 报文后，同样以 Change Cliper Spec 报文作为回应</li><li>接着服务端发送 Finish 报文给客户端，表示服务端已正确解析客户端发送的整体校验值，至此，SSL 握手的过程结束</li><li>随后开始使用 HTTP 协议传输使用 master secret 加密过的数据</li></ol><p><img src="'+i+'" alt=""></p><blockquote><p>证书需要向正规的服务商申请，而且浏览器内置了一个信任的 CA 证书列表，如果证书不是来自这个列表那么校验不通过</p></blockquote><p>TLS 协议安全性几个关键的点：</p><ul><li>证书无法伪造 (证书是向 CA 申请的)</li><li>证书私钥不被泄漏 (保证服务端不被攻击，私钥被盗)</li><li>域名管理权不泄漏</li><li>CA 坚守原则 (CA 不随意发证书)</li></ul><h3 id="_3-3-题目-https-加密过程是怎样的" tabindex="-1">3.3 题目：https 加密过程是怎样的 <a class="header-anchor" href="#_3-3-题目-https-加密过程是怎样的" aria-label="Permalink to &quot;3.3 题目：https 加密过程是怎样的&quot;">​</a></h3><h2 id="_4-http-2-0" tabindex="-1">4 http 2.0 <a class="header-anchor" href="#_4-http-2-0" aria-label="Permalink to &quot;4 http 2.0&quot;">​</a></h2><h3 id="_4-1-知识点" tabindex="-1">4.1 知识点 <a class="header-anchor" href="#_4-1-知识点" aria-label="Permalink to &quot;4.1 知识点&quot;">​</a></h3><p>http2 是由 Google 主导推出的协议，于 2015 年发布</p><p><strong>http2 做的改进：</strong></p><ol><li><code>HTTP/2</code> 是一个二进制协议，增加了数据传输的效率</li><li><code>HTTP/2</code> 是可以在一个 <code>TCP</code> 链接中并发请求多个 <code>HTTP</code> 请求，移除了 <code>HTTP/1.1</code> 中的串行请求</li><li><code>HTTP/2</code> 会压缩头，如果你同时发出多个请求，他们的头是一样的或是相似的，那么，协议会帮你消除重复的部分</li><li><code>HTTP/2</code> 允许服务端在客户端放 <code>cache</code>，又叫服务端 <code>push</code>，也就是说，你没有请求的东西，我服务端可以先送给你放在你的本地缓存中。比如，你请求 X，我服务端知道 X 依赖于 Y，虽然你没有的请求 Y，但我把把 Y 跟着 X 的请求一起返回客户端</li></ol><h3 id="_4-1-http2-0-做了哪些改进" tabindex="-1">4.1 http2.0 做了哪些改进 <a class="header-anchor" href="#_4-1-http2-0-做了哪些改进" aria-label="Permalink to &quot;4.1 http2.0 做了哪些改进&quot;">​</a></h3><h2 id="_5-http-3-0" tabindex="-1">5 http 3.0 <a class="header-anchor" href="#_5-http-3-0" aria-label="Permalink to &quot;5 http 3.0&quot;">​</a></h2><h3 id="_5-1-知识点" tabindex="-1">5.1 知识点 <a class="header-anchor" href="#_5-1-知识点" aria-label="Permalink to &quot;5.1 知识点&quot;">​</a></h3><p><strong>http2 的不足：</strong></p><p>若干个 <code>HTTP</code> 的请求在复用一个 <code>TCP</code> 的连接，底层的 <code>TCP</code> 协议是不知道上层有多少个 <code>HTTP</code> 的请求的，所以，一旦发生丢包，造成的问题就是所有的 <code>HTTP</code> 请求都必需等待这个丢了的包被重传回来</p><p><strong>http3 做的改进：</strong></p><ul><li><code>http3</code> 把 <code>HTTP</code> 底层的 <code>TCP</code> 协议改成了 <code>UDP</code></li></ul><h3 id="题目-http2-0-有哪些不足-http3-0-是什么" tabindex="-1">题目：http2.0 有哪些不足，http3.0 是什么 <a class="header-anchor" href="#题目-http2-0-有哪些不足-http3-0-是什么" aria-label="Permalink to &quot;题目：http2.0 有哪些不足，http3.0 是什么&quot;">​</a></h3><h2 id="_6-websocket" tabindex="-1">6 websocket <a class="header-anchor" href="#_6-websocket" aria-label="Permalink to &quot;6 websocket&quot;">​</a></h2><h3 id="题目-websocket-建立过程" tabindex="-1">题目：websocket 建立过程 <a class="header-anchor" href="#题目-websocket-建立过程" aria-label="Permalink to &quot;题目：websocket 建立过程&quot;">​</a></h3><h2 id="_7-tcp" tabindex="-1">7 tcp <a class="header-anchor" href="#_7-tcp" aria-label="Permalink to &quot;7 tcp&quot;">​</a></h2><h3 id="_7-1-三次握手" tabindex="-1">7.1 三次握手 <a class="header-anchor" href="#_7-1-三次握手" aria-label="Permalink to &quot;7.1 三次握手&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><ul><li>浏览器发起请求，发送初始化的 Sequence Number <code>x</code></li><li>服务器回复收到请求，发送 ACK <code>x-1</code>，同时发送服务端初始化的 Sequence Number <code>y</code></li><li>浏览器回复收到请求，发送 ACK <code>y+1</code></li></ul><p><strong>说明：</strong></p><ul><li><strong>seq：</strong> <code>Sequence Number</code> 是包的序号，用来解决网络包乱序（reordering）问题</li><li><strong>ACK：</strong> <code>Acknowledgement Number</code> 就是 ACK——用于确认收到，用来解决不丢包的问题</li><li><strong>SYN：</strong> <code>Synchronize Sequence Numbers</code> 初始化的 Sequence Number，这个号要作为以后的数据通信的序号</li></ul><p><strong>三次握手的作用：</strong></p><ol><li>建立连接</li><li>初始化 Sequence Number 的初始值，通信的双方要互相通知对方自己的初始化的 Sequence Number，这个过程叫 SYN。这个号要作为以后的数据通信的序号，以保证应用层接收到的数据不会因为网络上的传输的问题而乱序</li></ol><h3 id="_7-2-四次挥手" tabindex="-1">7.2 四次挥手 <a class="header-anchor" href="#_7-2-四次挥手" aria-label="Permalink to &quot;7.2 四次挥手&quot;">​</a></h3><ul><li>浏览器发送关闭连接 FIN</li><li>服务器发送收到 ACK</li><li>服务器发送关闭连接 FIN</li><li>浏览器发送收到 ACK</li></ul><h3 id="题目-三次握手过程" tabindex="-1">题目：三次握手过程 <a class="header-anchor" href="#题目-三次握手过程" aria-label="Permalink to &quot;题目：三次握手过程&quot;">​</a></h3><h3 id="题目-tcp-滑动窗口是什么" tabindex="-1">题目：tcp 滑动窗口是什么 <a class="header-anchor" href="#题目-tcp-滑动窗口是什么" aria-label="Permalink to &quot;题目：tcp 滑动窗口是什么&quot;">​</a></h3><h3 id="题目-tcp-重试机制" tabindex="-1">题目：tcp 重试机制 <a class="header-anchor" href="#题目-tcp-重试机制" aria-label="Permalink to &quot;题目：tcp 重试机制&quot;">​</a></h3><h2 id="_8-udp" tabindex="-1">8 udp <a class="header-anchor" href="#_8-udp" aria-label="Permalink to &quot;8 udp&quot;">​</a></h2><h3 id="_8-1-知识点" tabindex="-1">8.1 知识点 <a class="header-anchor" href="#_8-1-知识点" aria-label="Permalink to &quot;8.1 知识点&quot;">​</a></h3><p><code>UDP</code> 提供不可靠服务，具有 <code>TCP</code> 所没有的优势：</p><ul><li><strong>UDP 无连接：</strong> 时间上不存在建立连接需要的时延。空间上，TCP 需要在端系统中维护连接状态，需要一定的开销。此连接装入包括接收和发送缓存，拥塞控制参数和序号与确认号的参数。UDP 不维护连接状态，也不跟踪这些参数，开销小。空间和时间上都具有优势。</li><li><strong>UDP 没有拥塞控制：</strong> 应用层能够更好的控制要发送的数据和发送时间，网络中的拥塞控制也不会影响主机的发送速率。某些实时应用要求以稳定的速度发送，能容忍一些数据的丢失，但是不能允许有较大的时延（比如实时视频，直播等）</li><li><strong>UDP 不保证可靠交付：</strong> 所有维护传输可靠性的工作需要用户在应用层来完成。没有 TCP 的确认机制、重传机制。如果因为网络原因没有传送到对端，UDP 也不会给应用层返回错误信息</li><li><strong>UDP 常用一次性传输比较少量数据的网络应用：</strong> 如 DNS,SNMP 等，因为对于这些应用，若是采用 TCP，为连接的创建，维护和拆除带来不小的开销。</li><li><strong>UDP 也常用于多媒体应用：</strong> 如 IP 电话，实时视频会议，流媒体等。数据的可靠传输对他们而言并不重要，TCP 的拥塞控制会使他们有较大的延迟，也是不可容忍的</li></ul><h2 id="_9-跨域" tabindex="-1">9 跨域 <a class="header-anchor" href="#_9-跨域" aria-label="Permalink to &quot;9 跨域&quot;">​</a></h2><p><strong>jsonp：</strong></p><ul><li>jsonp 本质不是 ajax 请求</li><li>需要先在前端的 js 中定义一个回调函数</li><li>然后生成 script 标签，发请求给后端，只支持 get 请求</li><li>后端可以拿到回调函数名，把数据作为回调函数的参数传回去</li><li>前端就能接收到数据</li></ul>',64)])])}const T=e(h,[["render",n]]);export{b as __pageData,T as default};
